static void clear(void){eadk_display_push_rect_uniform(eadk_screen_rect,BG);}
static void text(const char *s,int x,int y,bool invert){eadk_display_draw_string(s,(eadk_point_t){x,y},invert,FG,BG);}
static void wait_release(void){while(eadk_keyboard_scan().bits) eadk_timing_msleep(25);}
static int key(void){eadk_keyboard_state_t k=eadk_keyboard_scan(); if(eadk_keyboard_key_down(k,eadk_key_up))return 1; if(eadk_keyboard_key_down(k,eadk_key_down))return 2; if(eadk_keyboard_key_down(k,eadk_key_ok))return 3; if(eadk_keyboard_key_down(k,eadk_key_back))return 4; if(eadk_keyboard_key_down(k,eadk_key_left))return 5; if(eadk_keyboard_key_down(k,eadk_key_right))return 6; return 0;}
static void header(const char *label){clear();text("AERO DATABASE",4,4,true);text(label,4,24,false);eadk_display_push_rect_uniform((eadk_rect_t){0,19,320,1},ACC);}
static void details(const Item *it,const char *type){header(type);text(it->code,4,42,true);text(it->name,4,65,false);text(it->extra,4,88,false);text("BACK: return",4,210,false);while(1){int k=key();if(k==4){wait_release();return;}eadk_timing_msleep(40);}}
static void browse(const Item *items,int n,const char *title){int sel=0,offset=0;while(1){header(title);for(int i=0;i<6;i++){int idx=offset+i;if(idx>=n)break;char line[40];snprintf(line,sizeof(line),"%s  %s",items[idx].code,items[idx].name);text(line,4,42+i*25,idx==sel);}text("UP/DN  OK: details  BACK",4,211,false);int k=key();if(k==1&&sel>0){sel--;if(sel<offset)offset--;}else if(k==2&&sel<n-1){sel++;if(sel>=offset+6)offset++;}else if(k==3){wait_release();details(&items[sel],title);}else if(k==4){wait_release();return;}eadk_timing_msleep(80);}}
int main(int argc,char *argv[]){int menu=0;while(1){header("OFFLINE REFERENCE");text("AIRCRAFT TYPES",15,62,menu==0);text("AIRLINES / CODES",15,92,menu==1);text("UP/DOWN select  OK open",15,135,false);text("BACK exits",15,158,false);int k=key();if(k==1||k==2){menu=1-menu;}else if(k==3){wait_release();if(menu==0)browse(aircraft,(int)(sizeof(aircraft)/sizeof(aircraft[0])),"AIRCRAFT");else browse(airlines,(int)(sizeof(airlines)/sizeof(airlines[0])),"AIRLINES");}else if(k==4)return 0;eadk_timing_msleep(80);}}
